draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw tree
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2, H/4);
  ctx.lineTo(W/2, H);
  ctx.stroke();

  // Draw swing
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + Math.sin(t) * 50);
  ctx.lineTo(W/2 + 50, H/2 + Math.sin(t) * 50);
  ctx.stroke();

  // Draw Scout
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + Math.sin(t) * 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + Math.sin(t) * 50 + 20);
  ctx.lineTo(W/2 + 50, H/2 + Math.sin(t) * 50 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + Math.sin(t) * 50 + 30);
  ctx.lineTo(W/2 + 30, H/2 + Math.sin(t) * 50 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + Math.sin(t) * 50 + 30);
  ctx.lineTo(W/2 + 70, H/2 + Math.sin(t) * 50 + 40);
  ctx.stroke();

  // Draw Tom Robinson
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 20);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 80, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 120, H/2 + 40);
  ctx.stroke();

  // Draw courthouse
  ctx.fillStyle = 'black';
  ctx.fillRect(W/2 - 150, H/2 + 50, 100, 50);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2 - 125, H/2 + 100);
  ctx.lineTo(W/2 - 75, H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
